mapper.select:
select id, guard_name as guardName, scope_type as scopeType, strategy_id as strategyId, symbol, exchange_code as exchangeCode, stop_loss_pct as stopLossPct, take_profit_pct as takeProfitPct, max_holding_minutes as maxHoldingMinutes, enabled, priority, remark from trade_position_guard where enabled = 1 and ( scope_type = 'GLOBAL'
or (scope_type = 'STRATEGY' and strategy_id = #{strategyId})
or ( scope_type = 'SYMBOL' and symbol = #{symbol}
and (exchange_code is null or upper(exchange_code) = upper(#{exchangeCode}))
and exchange_code is null
)
) order by case scope_type when 'SYMBOL' then 3 when 'STRATEGY' then 2 else 1 end desc, priority desc, id desc limit 1

select date_format(min(created_at), '%Y-%m-%d %H:%i:%s')
from position_change_log
where exchange_code = #{exchangeCode}
  and symbol = #{symbol}
  and side = #{side}
  and after_quantity > 0
  and id > ifnull((
    select max(id)
    from position_change_log
    where exchange_code = #{exchangeCode}
      and symbol = #{symbol}
      and side = #{side}
      and after_quantity = 0
  ), 0)
